/* CLS CRE global page behaviors: scroll-reveal, nav state, mobile menu, footer year.
   Referenced by pages that carry no inline nav/reveal scripts. */
(function(){'use strict';
function initReveal(){
  var els=document.querySelectorAll('.reveal:not(.visible)');
  if(!els.length)return;
  if('IntersectionObserver' in window){
    var obs=new IntersectionObserver(function(entries){
      entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target);}});
    },{threshold:0,rootMargin:'0px 0px -40px 0px'});
    els.forEach(function(el){obs.observe(el);});
  }else{
    els.forEach(function(el){el.classList.add('visible');});
  }
}
function initNav(){
  var nav=document.getElementById('nav');
  if(nav){window.addEventListener('scroll',function(){nav.classList.toggle('scrolled',window.scrollY>20);});}
  var mt=document.getElementById('mobileToggle'),nl=document.getElementById('navLinks');
  if(mt&&nl&&!mt.dataset.bound){
    mt.dataset.bound='1';
    mt.addEventListener('click',function(){nl.classList.toggle('open');mt.setAttribute('aria-expanded',nl.classList.contains('open'));});
    nl.querySelectorAll('a').forEach(function(l){l.addEventListener('click',function(){nl.classList.remove('open');});});
  }
}
function initYear(){
  var fy=document.getElementById('fyear');
  if(fy&&!fy.textContent)fy.textContent=new Date().getFullYear();
}
function init(){initReveal();initNav();initYear();}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}
})();
